RENOIR_OPENING = [[['BUY_PRODUCT', 'WHEAT', 30]], [['SELL', 'WHEAT', 25], ['BUY_SEED', 'WHEAT', 7], ['BUY_SEED', 'MELON', 12], ['HIRE'], ['HIRE'], ['HIRE'], ['HIRE'], ['HIRE'], ['BUY_ANIMAL', 'COW', 2], ['BUY_ANIMAL', 'SHEEP', 2]], [['SELL', 'WHEAT', 1]]]
OPENING_SWITCH_STEP = 3

def act(observation, configuration):
    player = int(observation.get("player", 0))
    step = min(int(observation.get("step", 0)), 719)
    action = copy.deepcopy(ACTIONS[step])
    if step < OPENING_SWITCH_STEP:
        action["market"] = copy.deepcopy(RENOIR_OPENING[step])
    hands = (observation.get("farms") or [])[player].get("hands") or []
    action["hands"] = action["hands"][:len(hands)]
    return action

def agent(observation, configuration): return act(observation, configuration)
